  addressVillageTracts,
  addressVillages,
  nrcStates,
  nrcTownships,
  NRCTownshipVariations,
  addressVillageData,
  addressVillageTractData,
  addressWardData,
  contactTypes,
  typeofBusinesses,
  mainBusinessCategories,
  subBusinessCategories,
  documentTypes,
  blacklistCustomers,
  nrcRemarks,
  table,
  menuApplicationSetup,
  numberSeries,
  users,
  user,
  workflows,
  approvalWorkflows,
  fileAttaches,
  documentAccesses,
  signers,
  cmcoUsers,
  agents,
  blackListArea,
  excludeBlackListArea,
  emailSetups,
};

export default reducerMap;
